UPDATE lessons SET title='Year 3: Spell with sounds and syllables', data=json_patch(data,'{"child_mission":"Hear the parts in longer words, choose letters for sounds, and check your spelling using a repeatable method.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Collect independent word breakdowns, a corrected sentence and explanations, plus two written spelling responses. Parent may record an oral segmentation as evidence.","explicit_teaching":null,"extension":"Find four words from your current book with different long-vowel spelling patterns. Sort them, check each spelling and explain any unexpected pattern.","follow_up_challenges":null,"guided_practice":"WE DO — try each first.\n1. Clap and segment \"computer\". Compare: com-pu-ter, three spoken beats. Different accents may make syllable boundaries feel slightly different, but the word is commonly three syllables.\n2. Identify graphemes in \"chop\". Compare: ch | o | p. The first two letters work together for /ch/.\n3. Choose the conventional spelling \"play\" or \"plai\" in \"We ___ after lunch\". Compare: play, with ay at the end, as in day and stay.\n4. Proofread \"A sheep sleped in the feeld\". Compare: \"A sheep slept in the field.\" Check both uncertain words against familiar spellings.","hoard_words":null,"independent_task":"YOU DO — do not copy guided words.\n1. Segment \"butterfly\" into spoken syllables and explain how many beats you hear.\n2. Identify sound-to-letter groups in \"brush\"; explain why the starting br uses two sounds but final sh is one grapheme for one sound.\n3. Complete and explain the /ay/ spelling in \"We waited for the r__n to stop\" and in \"It was a sunny d__\".\n4. Proofread \"The rabit hopd beside the trea\". Write the complete corrected sentence, circle or list each word changed and explain how you checked one tricky spelling.","interactive_activities":null,"learning_area":"English","learning_intention":"Learn to break words into spoken syllables, identify their sounds, connect sounds with letter patterns and proofread a short sentence.","lesson_number":3,"lesson_role":"Language and spelling","materials":["Paper or typing space","Optional pencil for sound boxes"],"offline_alternative":"Use claps or taps to hear syllables, draw boxes for graphemes, and write a proofreading passage by hand. Save the paper page or describe it in the typing area.","outcome_codes":["EN2-SPELL-01"],"parent_notes":"Parent: Independent answers: 1. but-ter-fly has three spoken syllables. 2. brush can be heard as /b/ /r/ /u/ /sh/: br contains two consonant sounds; sh represents one sound with two letters. 3. rain uses ai; day uses ay. 4. \"The rabbit hopped beside the tree.\" Rabbit has double b, hopped has double p before ed in this spelling, and tree has ee for its long vowel sound.\n\nParent: Written model 1: cat-er-pil-lar is commonly spoken in four beats. Clapping one beat at a time helps me avoid leaving out a part.\n\nParent: Written model 2: The chicken sat on the branch. Chicken uses ch for the /ch/ sound; branch also has ch at the end.\n\nParent: Observe whether the learner segments aloud, checks spelling against known patterns and can explain corrections rather than guessing. Keep sample answers out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"Elephant is commonly pronounced el-e-phant, giving three spoken beats rather than one for each letter.","options":["1","2","3","8"],"question":"How many spoken syllables are commonly heard in \"elephant\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Tomato commonly has three syllables: to-ma-to. The boundaries are about pronunciation, not letter count.","options":["to-ma-to","tom-at-o-o","t-o-m-a-t-o","toma-toe"],"question":"Which divides \"tomato\" into its common spoken beats?","type":"multiple_choice"},{"correct_index":1,"explanation":"The letters ch work together for the /ch/ sound at the start of chair.","options":["c","ch","ha","ai"],"question":"Which grapheme represents the initial sound in \"chair\"?","type":"multiple_choice"},{"correct_index":1,"explanation":"Ship is conventionally analysed into three phonemes: /sh/, /i/ and /p/, even though it has four letters.","options":["2","3","4","5"],"question":"How many sound groups are /sh/ /i/ /p/ in \"ship\"?","type":"multiple_choice"},{"correct_index":1,"explanation":"Train uses ai for the long /ay/ sound, as in rain, and the word ends with n.","options":["trayne","train","trayn","traine"],"question":"Which is the conventional spelling?","type":"multiple_choice"},{"correct_index":2,"explanation":"Play ends with ay for the long /ay/ sound; the other options do not use its conventional spelling.","options":["pla i","plai","play","plei"],"question":"Which word ends in the common ay spelling?","type":"multiple_choice"},{"correct_index":2,"explanation":"Yellow contains double l and ends with ow. Sounding the word is helpful, but its letter pattern must also be learned.","options":["yello","yelow","yellow","yelloe"],"question":"Which spelling correctly names the colour?","type":"multiple_choice"},{"correct_index":1,"explanation":"Rabbit is conventionally spelled with double b and it, so the second sentence is the correctly spelled one.","options":["The rabit ran.","The rabbit ran.","The rabbet ran.","The rabet ran."],"question":"Which sentence contains no obvious spelling errors?","type":"multiple_choice"},{"explanation":"Syllables divide a word into manageable spoken beats, though boundaries and pronunciation can vary by accent.","marking_guide":"Accept a plausible spoken segmentation with four syllables, recognising pronunciation variation; require a clear explanation of segmentation for spelling.","question":"Separate \"caterpillar\" into commonly spoken syllables and describe how clapping helps you spell long words.","sample_answer":"cat-er-pil-lar is commonly spoken in four beats. Clapping one beat at a time helps me avoid leaving out a part.","type":"short_answer"},{"explanation":"A proofreading explanation identifies the changed letter groups, rather than supplying an unexplained replacement.","marking_guide":"Require both conventional spellings chicken and branch, and a reasonable sound-letter or spelling-pattern explanation.","question":"Correct \"The chiken sat on the brench\" and explain the spelling of one corrected word.","sample_answer":"The chicken sat on the branch. Chicken uses ch for the /ch/ sound; branch also has ch at the end.","type":"short_answer"}],"resources":null,"response_prompt":"Write four numbered answers, including syllable divisions, grapheme explanation, both /ay/ spellings and a corrected sentence with reasons.","review_status":"unreviewed","seed_key":"s2-eng-y3-w01-l3","sort_activity":null,"source_note":"Proposed Stage 2 spelling outcome. Preserve and verify the existing card mapping against current NESA content points before acceptance.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Think about hearing words in smaller parts.","Listen for beats and smaller sound units before spelling.","You will use syllables, graphemes, familiar patterns and proofreading."],"guided":["Try the word before reading its correction.","Mark syllables, digraphs or spelling patterns, depending on the prompt.","For chop, the first grapheme is ch, not c alone."],"learn":["Split the model word into natural spoken parts.","Work through sun and shine as separate chunks.","Sunshine joins sun and shine; preserve sh and the final silent e."],"quiz":["Read every option before you tap one.","Notice when two letters work together for a single sound.","Count spoken beats separately from the number of letters."],"submit":["Check every labelled response is present.","Read back each corrected word within its whole sentence.","Keep syllable separators and explanations so your parent can see your strategy."],"teach0":["Say the whole word normally first.","Tap each spoken beat, not each letter.","Banana separates into ba-na-na, three beats."],"teach1":["Look for letters that work together for a sound.","Stretch the word and identify each sound before writing.","In sheep, sh and ee are each two-letter graphemes for one sound."],"teach2":["Some vowels have more than one spelling choice.","Compare your word with known examples like rain and day.","Train resembles rain and is conventionally spelled with ai."],"teach3":["Read slowly and stop at uncertain words.","Check the middle of the word as well as its beginning.","Yellow needs two ls, while umbrella also needs double l."],"write":["Complete the four independent tasks in order.","Explain both the letter pattern and the reason for a correction.","For brush, /b/ and /r/ are separate sounds but final sh is one grapheme."]},"subject":"English","success_criteria":["I can clap the beats in a word and separate its syllables.","I can say sounds slowly and choose a plausible letter pattern for each.","I can explain a tricky spelling choice instead of guessing.","I can reread and correct spelling in my own sentence."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":2,"explanation":"Banana has three spoken syllables: ba, na and na. Counting individual letters does not show spoken beats.","options":["ban-ana","b-a-n-a-n-a","ba-na-na","bana-naa"],"question":"Which gives the spoken beats in \"banana\"?","type":"multiple_choice"},"example":"WATCH MY THINKING\nFor \"fantastic\" I say fan-tas-tic: three beats. I write fan | tas | tic before joining fantastic. I do not clap once for every letter; I listen for natural parts.\n\nYOUR SMALL TRY\nSay \"banana\" slowly and list its spoken syllables before comparing.\n\nCOMPARE AFTER TRYING\nba-na-na has three syllables. If you got six, you counted the letters instead of its beats.","explain":"A syllable is one spoken beat in a word; pronounce the whole word naturally and then clap its beats.\n\nBreaking a long word into manageable spoken parts makes it easier to remember and spell.\n\nSay \"umbrella\" normally. Then slow it down: um-brel-la. You can clap three times. The number of letters does not determine the number of beats: \"elephant\" has three spoken beats, el-e-phant, even though it has eight letters. Some words change slightly depending on accent; listen for the spoken vowel-centred beats in your own careful pronunciation. Writing the syllables on paper can help you keep track of the word without skipping a part.","icon":"🔤","notice":"A common mistake is treating each letter as its own syllable. Speak the complete word aloud and tap its beats, then write one box per beat rather than per letter.","title":"Hear syllables before you write","visual":[{"alt":"Umbrella divided into the three spoken syllables um, brel and la in three labelled boxes.","caption":"A syllable is one spoken beat; a syllable can contain several letters.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 145\"><rect x=\"12\" y=\"33\" width=\"172\" height=\"71\" rx=\"10\" fill=\"#e4f4ed\" stroke=\"#246e5b\" stroke-width=\"2\"/><rect x=\"214\" y=\"33\" width=\"172\" height=\"71\" rx=\"10\" fill=\"#e4f4ed\" stroke=\"#246e5b\" stroke-width=\"2\"/><rect x=\"416\" y=\"33\" width=\"172\" height=\"71\" rx=\"10\" fill=\"#e4f4ed\" stroke=\"#246e5b\" stroke-width=\"2\"/><g font-size=\"26\" fill=\"#243544\" text-anchor=\"middle\"><text x=\"98\" y=\"78\">um</text><text x=\"300\" y=\"78\">brel</text><text x=\"502\" y=\"78\">la</text></g><text x=\"300\" y=\"133\" text-anchor=\"middle\" font-size=\"20\" fill=\"#243544\">umbrella = um / brel / la (three spoken beats)</text></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"Umbrella looks long. Should I write one letter for every clap?","who":"pip"},{"text":"Clap spoken beats, not letters. Umbrella is often um, brel, la: three beats.","who":"juno"},{"text":"So a beat can hold several letters, and two letters can make one sound.","who":"pip"},{"pause_after":true,"text":"Pause here. Clap a long word from this lesson and count the beats before spelling it.","who":"juno"}]}],"title":"Hear the beats before you write","transcript":"Pip: Umbrella looks long. Should I write one letter for every clap?\nJuno: Clap spoken beats, not letters. Umbrella is often um, brel, la: three beats.\nPip: So a beat can hold several letters, and two letters can make one sound.\nJuno: Pause here. Clap a long word from this lesson and count the beats before spelling it."}}]},{"check":{"correct_index":2,"explanation":"The letters sh are one grapheme representing the /sh/ sound. The following i and p represent different sounds.","options":["si","ip","sh","hi"],"question":"Which two letters work together for one starting sound in \"ship\"?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI stretch \"shop\": /sh/ /o/ /p/. I write the letters sh | o | p, then read the complete word to check it says \"shop\". I do not split the s and h into separate sounds.\n\nYOUR SMALL TRY\nIn \"chat\", which letters work together for its starting sound?\n\nCOMPARE AFTER TRYING\nThe letters ch work together for the /ch/ sound. The rest of the word gives /a/ and /t/.","explain":"A phoneme is a speech sound; a grapheme is the letter or letter group we use to represent it.\n\nListening for individual sounds helps you avoid losing consonants or choosing letters merely by visual guessing.\n\nSay \"sheep\" slowly. You can hear /sh/, a long /ee/ vowel and /p/. It has five letters but only three sound units in this analysis, because sh and ee work as pairs. In \"ship\", sh still represents one sound but the vowel is short and spelled with i. Listen to the sound first, then look for the likely letters. Use a word you know with the same sound to support the spelling choice.","icon":"🔤","notice":"A common mistake is assuming every spoken sound must be written with exactly one letter. Notice common multi-letter graphemes such as sh, ch, th, ai and ee; the sound and number of letters are not always equal.","title":"Hear sounds inside each syllable","visual":[{"alt":"Sheep split into three grapheme units sh, ee and p; some sounds require two letters.","caption":"Two letters can work together for one sound, as sh and ee do in sheep.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 150\"><g stroke=\"#316994\" stroke-width=\"2\" fill=\"#eaf3fc\"><rect x=\"16\" y=\"24\" width=\"180\" height=\"70\" rx=\"12\"/><rect x=\"214\" y=\"24\" width=\"180\" height=\"70\" rx=\"12\"/><rect x=\"412\" y=\"24\" width=\"180\" height=\"70\" rx=\"12\"/></g><g font-size=\"26\" text-anchor=\"middle\" fill=\"#22374c\"><text x=\"106\" y=\"68\">sh</text><text x=\"304\" y=\"68\">ee</text><text x=\"502\" y=\"68\">p</text></g><text x=\"305\" y=\"126\" font-size=\"19\" text-anchor=\"middle\" fill=\"#22374c\">sheep: /sh/ + /ee/ + /p/</text></svg>"}]},{"check":{"correct_index":2,"explanation":"Train is conventionally written with ai. Comparing it with the familiar spelling rain helps remember the pattern.","options":["trayn","traen","train","trane"],"question":"Which spelling is conventional for a vehicle travelling on rails?","type":"multiple_choice"},"example":"WATCH MY THINKING\nTo spell \"paint\", I hear /p/ /ay/ /n/ /t/. I remember \"rain\" has ai for the /ay/ sound here, so I write p-ai-n-t, then reread the whole word and check it against my known pattern.\n\nYOUR SMALL TRY\nWhich spelling pattern completes \"tr__n\" when the word means a railway vehicle?\n\nCOMPARE AFTER TRYING\nThe word is \"train\" and uses ai, like \"rain\". \"Trayn\" is a reasonable sound guess but not the conventional spelling.","explain":"When several letter patterns could spell a sound, compare familiar words and use meaning or a reference to choose.\n\nEnglish uses more than one grapheme for some sounds, so sounding out is a starting strategy, not a guarantee.\n\nThe long /ay/ sound appears in \"rain\" (ai), \"day\" (ay) and \"cake\" (a-e). A useful pattern is often ai inside a syllable and ay at the end, but English has exceptions. When you write \"play\", think of familiar words \"day\" and \"stay\". When you write \"train\", think of \"rain\". If a word still seems uncertain, check it in a reliable dictionary or spelling list instead of pretending there is a rule with no exceptions.","icon":"🔤","notice":"A common mistake is using a useful spelling pattern as though it has no exceptions. Treat analogies as clues, then confirm unfamiliar words with an approved word list or dictionary.","title":"Choose a spelling pattern, then check meaning"},{"check":{"correct_index":1,"explanation":"Yellow is spelled with double l and ow. Reading the complete word, not only the first sound, catches the mistake.","options":["The yelow boat sailed.","The yellow boat sailed.","The yelloe boat sailed.","The yello boat sailed."],"question":"Which sentence is conventionally spelled?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI mark cheld, yelow and umbrela as uncertain. I check each spelling carefully and rewrite: \"The child held a yellow umbrella.\" I compare every corrected word with the original before deciding that I am finished.\n\nYOUR SMALL TRY\nProofread \"The brite moon shone over the gardin.\" Identify the two uncertain spellings.\n\nCOMPARE AFTER TRYING\nThe conventional spellings are \"bright\" and \"garden\". Bright has igh for its long vowel sound; garden has e rather than i in the last syllable.","explain":"Check your sentence by reading slowly, finding any word that looks or sounds uncertain and checking its syllables or graphemes.\n\nProofreading can catch missed sounds and spelling errors that disappear when you read quickly for meaning.\n\nLook at \"The cheld held a yelow umbrela.\" Read each word slowly. \"Child\" contains i rather than e; \"yellow\" has ll; \"umbrella\" ends with double l before a. Saying um-brel-la helps remember all three parts, but the double letter still needs visual memory or a checked reference. Finally reread the corrected whole sentence with its capital and full stop.","icon":"🔤","notice":"A common mistake is checking only the first and last sounds of a word and overlooking middle sounds or doubled letters. Point to each sound group, reread the entire spelling and check uncertain words rather than guessing confidently.","title":"Proofread your writing one word at a time"}],"title":"Year 3: Spell with sounds and syllables","unit_number":1,"unit_title":"Narrative: story elements and planning","week":1,"week_in_unit":1,"word_challenges":null,"worked_example":"I DO: Spell \"sunshine\" by listening and checking. First say it naturally: sun-shine (two syllables). The first part has /s/ /u/ /n/ and is written sun. The second begins with /sh/, written sh, and has a long /i/ vowel represented by i-e around the n: shine. Join sun + shine to make sunshine. Reread the whole word; check that sh stays together and the final e is not forgotten. Write \"The sunshine warmed the path\" as a complete sentence to check the word in context.","worked_visuals":[{"alt":"Umbrella divided into the three spoken syllables um, brel and la in three labelled boxes.","caption":"A syllable is one spoken beat; a syllable can contain several letters.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 145\"><rect x=\"12\" y=\"33\" width=\"172\" height=\"71\" rx=\"10\" fill=\"#e4f4ed\" stroke=\"#246e5b\" stroke-width=\"2\"/><rect x=\"214\" y=\"33\" width=\"172\" height=\"71\" rx=\"10\" fill=\"#e4f4ed\" stroke=\"#246e5b\" stroke-width=\"2\"/><rect x=\"416\" y=\"33\" width=\"172\" height=\"71\" rx=\"10\" fill=\"#e4f4ed\" stroke=\"#246e5b\" stroke-width=\"2\"/><g font-size=\"26\" fill=\"#243544\" text-anchor=\"middle\"><text x=\"98\" y=\"78\">um</text><text x=\"300\" y=\"78\">brel</text><text x=\"502\" y=\"78\">la</text></g><text x=\"300\" y=\"133\" text-anchor=\"middle\" font-size=\"20\" fill=\"#243544\">umbrella = um / brel / la (three spoken beats)</text></svg>"},{"alt":"Sheep split into three grapheme units sh, ee and p; some sounds require two letters.","caption":"Two letters can work together for one sound, as sh and ee do in sheep.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 150\"><g stroke=\"#316994\" stroke-width=\"2\" fill=\"#eaf3fc\"><rect x=\"16\" y=\"24\" width=\"180\" height=\"70\" rx=\"12\"/><rect x=\"214\" y=\"24\" width=\"180\" height=\"70\" rx=\"12\"/><rect x=\"412\" y=\"24\" width=\"180\" height=\"70\" rx=\"12\"/></g><g font-size=\"26\" text-anchor=\"middle\" fill=\"#22374c\"><text x=\"106\" y=\"68\">sh</text><text x=\"304\" y=\"68\">ee</text><text x=\"502\" y=\"68\">p</text></g><text x=\"305\" y=\"126\" font-size=\"19\" text-anchor=\"middle\" fill=\"#22374c\">sheep: /sh/ + /ee/ + /p/</text></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w01-l3' AND family_id IS NULL;
